INSERT INTO Concepts VALUES(395920,'walk','B','Verb','6','(LDV) an animal moves on foot to some place','','A________',replace('4|1|31|18|p|A|animalA||||||||\n4|9|30|20|p|A|animalA||||||||\n4|27|7|7|p|A|animalA||||||||\n4|27|7|19|p|A|animalA||||||||\n4|27|8|7|p|A|goatA||||||||\n7|3|3|4|p|A|chickenA||||||||\n','\n',char(10)),'4,27,8,7|(NPA|goat|)|(VP|walk|)|(NPN|on|sheep|)|~The goat walked on the sheep.',1);
INSERT INTO Concepts VALUES(395921,'walk-away','A','Verb','3','(LDV) to walk away from someone or some place (John walked away from Mary.)','','A__d_____',replace('4|2|23|4|p|A|oxA||||||||\n4|9|24|7|p|A|SaulA|||caveA|||||\n4|42|4|30|p|A|JesusA|||personA|||||\n','\n',char(10)),replace('4,42,4,30|(NPA|Jesus|)|(VP|walk-away|)|(NPs|person|)|~Jesus walked away from the people.\n4,2,23,4|(NPA|ox|)|(VP|walk-away|)|~The ox walked away.\n','\n',char(10)),1);
