PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE Concepts (
	'id' 						INTEGER PRIMARY KEY,
	'stem' 					TEXT,
	'sense' 					TEXT,
	'part_of_speech' 		TEXT,
	'occurrences' 			TEXT,
	'gloss' 					TEXT,
	'brief_gloss' 			TEXT,
	'categorization' 		TEXT,
	'examples' 				TEXT,
	'curated_examples'	TEXT,
	'level' 					INTEGER
);
CREATE TABLE Version(version TEXT);
COMMIT;
